// === Tab: mySketch ===
// by SamuelYAN
// more works //
   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

let mySize;
let seed = Math.random() * 2000;
let tile_Count = 20;
let cubes = [];

// colors
let colors2 = "fc4155-16ab9b-00000000"
  .split("-")
  .map((a) => "#" + a);
// color #RRGGBBAA
let colors1 = "fc4155-16ab9b-00000000"
  .split("-")
  .map((a) => "#" + a);
let colors3 = "fc415580-16ab9b80-00000000"
  .split("-")
  .map((a) => "#" + a);

function setup() {
  pixelDensity(5);
  mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize);
  randomSeed(seed);
  noiseSeed(seed);
  background(0);

  let w = width / tile_Count;

  for (let i = 0; i < tile_Count; i++) {
    for (let j = 0; j < tile_Count; j++) {
      let scaleX = 1;
      let scaleY = 1;
      let x = i * w;
      let y = j * w;
      let ShapeItem = int(random(1,3));
      if (ShapeItem == 1) {
        cubes.push(
          new makeCubes(
            x ,
            y ,
            w * scaleX,
            w * scaleY
          )
        );
      }
    }
  }
}

function draw() {
  randomSeed(seed);
  noiseSeed(seed);
	background(0);
  for (let c of cubes) {
    c.display();
  }
}

class makeCubes {
  constructor(x, y, wx, wy) {
    this.x = x;
    this.y = y;
    this.wx = wx;
    this.wy = wy;
    this.plus = random(-100, 100);
    this.plusX = this.plus;
    this.plusY = this.plus;
    this.col1 = random(colors1);
    this.col2 = random(colors2);
    this.col3 = random(colors3);
    this.xscale = 1;
    this.yscale = 1;
    this.strWei = random(0.5,1.5)
  }

  display() {
    strokeWeight(this.strWei);
    //fill(this.col3);
    noFill();
    stroke(this.col1);
    push();
    translate(
      this.x + (this.wx * this.xscale) / 2,
      this.y + (this.wy * this.yscale) / 2
    );
    rectMode(CENTER);
    rect(0, 0, this.wx * this.xscale, this.wy * this.yscale);
    pop();

    noFill();
    stroke(this.col1);
    push();
    translate(
      this.x + (this.wx * this.xscale) / 2,
      this.y + (this.wy * this.yscale) / 2
    );
    line(
      (-this.wx * this.xscale) / 2,
      (-this.wy * this.yscale) / 2,
      (-this.wx * this.xscale) / 2 + this.plusX,
      (-this.wy * this.yscale) / 2 + this.plusY
    );
    line(
      (-this.wx * this.xscale) / 2,
      (this.wy * this.yscale) / 2,
      (-this.wx * this.xscale) / 2 + this.plusX,
      (this.wy * this.yscale) / 2 + this.plusY
    );
    line(
      (this.wx * this.xscale) / 2,
      (-this.wy * this.yscale) / 2,
      (this.wx * this.xscale) / 2 + this.plusX,
      (-this.wy * this.yscale) / 2 + this.plusY
    );
    line(
      (this.wx * this.xscale) / 2,
      (this.wy * this.yscale) / 2,
      (this.wx * this.xscale) / 2 + this.plusX,
      (this.wy * this.yscale) / 2 + this.plusY
    );
    pop();

    noStroke();
    fill(this.col3);
    push();
    translate(
      this.x + (this.wx * this.xscale) / 2 + this.plusX,
      this.y + (this.wy * this.yscale) / 2 + this.plusY
    );
    rectMode(CENTER);
    for (let i = 0; i < 4; i++) {
      rect(
        0,
        0,
        (this.wx - i * 8) * this.xscale,
        (this.wy - i * 8) * this.yscale
      );
    }
    pop();
  }
}

function keyTyped() {
  if (key === "s" || key === "S") {
    saveCanvas("NewCubes", "png");
  }
}

